/**
 * Configuration Module
 * 
 * Centralized configuration management with environment variable validation
 * This module ensures all required environment variables are present at startup
 */

/**
 * Required environment variables that must be set
 * Throws error if any are missing in production
 */
const validateConfig = () => {
  const required = [
    'DATABASE_URL',
    'STRIPE_SECRET_KEY',
    'ANTHROPIC_API_KEY',
  ];

  // Only require these in production
  if (process.env.NODE_ENV === 'production') {
    required.forEach(envVar => {
      if (!process.env[envVar]) {
        throw new Error(
          `❌ Missing required environment variable in production: ${envVar}\n` +
          `   Please set this environment variable before starting the application.`
        );
      }
    });
  } else {
    // In development, warn about missing variables but don't fail
    required.forEach(envVar => {
      if (!process.env[envVar]) {
        console.warn(`⚠️  Missing environment variable: ${envVar} (required in production)`);
      }
    });
  }
};

/**
 * Parse and validate configuration
 */
const config = {
  // Server Configuration
  port: (() => {
    const port = parseInt(process.env.PORT || '3000', 10);
    if (isNaN(port) || port < 1 || port > 65535) {
      throw new Error(`Invalid PORT: ${process.env.PORT}. Must be a number between 1 and 65535`);
    }
    return port;
  })(),

  host: process.env.HOST || 'localhost',

  nodeEnv: process.env.NODE_ENV || 'development',

  // CORS Configuration
  corsOrigin: process.env.CORS_ORIGIN || 'http://localhost:3000',

  // Rate Limiting Configuration
  rateLimit: {
    windowMs: (() => {
      const ms = parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10);
      if (isNaN(ms) || ms < 1000) {
        throw new Error('RATE_LIMIT_WINDOW_MS must be at least 1000ms');
      }
      return ms;
    })(),

    max: (() => {
      const max = parseInt(process.env.RATE_LIMIT_MAX || '100', 10);
      if (isNaN(max) || max < 1) {
        throw new Error('RATE_LIMIT_MAX must be at least 1');
      }
      return max;
    })(),
  },

  // Database Configuration
  database: {
    url: process.env.DATABASE_URL,
  },

  // Third-party Services Configuration
  stripe: {
    secretKey: process.env.STRIPE_SECRET_KEY,
  },

  anthropic: {
    apiKey: process.env.ANTHROPIC_API_KEY,
  },

  logfire: {
    token: process.env.LOGFIRE_TOKEN,
  },

  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
  },

  // Logging Configuration
  logging: {
    level: process.env.LOG_LEVEL || 'info',
    debug: process.env.DEBUG === 'true' || process.env.NODE_ENV === 'development',
  },

  // Request Configuration
  request: {
    timeoutMs: (() => {
      const timeout = parseInt(process.env.REQUEST_TIMEOUT_MS || '30000', 10);
      if (isNaN(timeout) || timeout < 1000) {
        throw new Error('REQUEST_TIMEOUT_MS must be at least 1000ms');
      }
      return timeout;
    })(),

    maxPayloadSize: process.env.MAX_PAYLOAD_SIZE || '10kb',
  },

  // Feature Flags
  features: {
    debug: process.env.DEBUG === 'true',
  },
};

// Validate configuration on module load
validateConfig();

module.exports = config;

// Export validation function for testing
module.exports.validateConfig = validateConfig;

// Export raw config for testing
module.exports.getRawConfig = () => config;

