```

### Issues Identified

| Issue | Impact | Severity |
|-------|--------|----------|
| Hardcoded `3000` port | Can't change port without editing code | 🟡 Medium |
| Hardcoded message | Misleading if port changes | 🟡 Medium |
| No env var support | Not production-ready | 🟡 Medium |
| No error handling | Stack traces expose internals | 🔴 High |
| No security headers | Vulnerable to attacks | 🔴 High |
| Exposed user emails | Privacy violation | 🔴 High |

---

### After: app.improved.js (✅ Production-Ready)

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const config = require('./config');

const app = express();

// ✅ Security middleware
app.use(helmet());
app.use(cors({
  origin: config.corsOrigin,  // ✅ From environment
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// ✅ Rate limiting
const limiter = rateLimit({
  windowMs: config.rateLimit.windowMs,      // ✅ Configurable
  max: config.rateLimit.max,                // ✅ Configurable
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// ✅ Body size limits
app.use(express.json({ limit: config.request.maxPayloadSize }));

app.get('/health', (req, res) => {
  res.status(200).json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
    environment: config.nodeEnv
  });
});

app.get('/users', (req, res) => {
  // ✅ No sensitive data exposed
  const users = [
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ];
  res.status(200).json({
    success: true,
    data: users,
    count: users.length
  });
});

// ✅ 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method
  });
});

// ✅ Global error handler
app.use((err, req, res, next) => {
  console.error(`[ERROR] ${err.status || 500}: ${err.message}`);
  const status = err.status || 500;
  const message = config.nodeEnv === 'production' 
    ? 'Internal Server Error' 
    : err.message;
  res.status(status).json({
    error: message,
    ...(config.nodeEnv === 'development' && {
      stack: err.stack,
      details: err.message
    })
  });
});

// ✅ Server startup with proper configuration
if (require.main === module) {
  const server = app.listen(config.port, config.host, () => {
    console.log(`
╭─────────────────────────────────────╮
│  🚀 Server Started Successfully     │
├─────────────────────────────────────┤
│  Host:        ${config.host.padEnd(24)} │
│  Port:        ${String(config.port).padEnd(24)} │
│  Environment: ${config.nodeEnv.padEnd(24)} │
│  CORS Origin: ${config.corsOrigin.padEnd(24)} │
╰─────────────────────────────────────╯
    `);
  });

  // ✅ Graceful shutdown
  process.on('SIGTERM', () => {
    console.log('\n⏹️  SIGTERM received, shutting down gracefully...');
    server.close(() => {
      console.log('✅ Server closed');
      process.exit(0);
    });
  });
}

module.exports = app;
```

### Issues Fixed

| Issue | Solution | Status |
|-------|----------|--------|
| Hardcoded port | Use `config.port` from environment | ✅ Fixed |
| Hardcoded message | Dynamic message from config values | ✅ Fixed |
| No env var support | Full configuration module | ✅ Fixed |
| No error handling | Global error handler implemented | ✅ Fixed |
| No security headers | Helmet middleware added | ✅ Fixed |
| Exposed user emails | Removed from response | ✅ Fixed |

---

## Configuration Comparison

### Before (❌ Hardcoded)
