  res.json({ data: 'sensitive' });
});

app.post('/login', (req, res) => {
  const { username, password } = req.body;
  // VULNERABLE: Storing plain password
  db.query('SELECT * FROM users WHERE username = ? AND password = ?',
    [username, password]);
