// Secure version of the application with security best practices implemented

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ============================================
// LOGGING CONFIGURATION
// ============================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.Console(),
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
}));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: process.env.RATE_LIMIT_MAX || 100,
  message: 'Too many requests, please try again later',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  skip: (req) => {
    // Skip rate limiting for health checks from internal IPs
    return req.path === '/health' && req.ip === '127.0.0.1';
  }
});

app.use(limiter);

// 4. Request Size Limiting
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: false }));

// 5. Request ID middleware for tracing
app.use((req, res, next) => {
  req.id = req.headers['x-request-id'] || `${Date.now()}-${Math.random()}`;
  res.setHeader('X-Request-ID', req.id);
  next();
});

// 6. Request logging middleware
app.use((req, res, next) => {
  logger.info({
    requestId: req.id,
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// ============================================
// AUTHENTICATION MIDDLEWARE
// ============================================

/**
 * Simple token-based authentication
 * In production, use JWT or OAuth2
 */
function authenticate(req, res, next) {
  const token = req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
    logger.warn({
      requestId: req.id,
      event: 'missing_auth_token',
      path: req.path
    });
    return res.status(401).json({ 
      error: 'Unauthorized',
      requestId: req.id 
    });
  }

  // Simple validation (replace with real JWT verification)
  if (!isValidToken(token)) {
    logger.warn({
      requestId: req.id,
      event: 'invalid_auth_token',
      path: req.path
    });
    return res.status(401).json({ 
      error: 'Invalid token',
      requestId: req.id 
    });
  }

  next();
}

/**
 * Validate token format (implement proper JWT verification)
 */
function isValidToken(token) {
  return token && token.length > 10; // Placeholder validation
}

// ============================================
// ROUTES
// ============================================

/**
 * Health Check Endpoint
 * Accessible without authentication for load balancers
 */
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    requestId: req.id
  });
});

/**
 * Get Users Endpoint
 * Protected with authentication
 * Limited response data (no email exposure)
 */
app.get('/users',
  authenticate,
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({
        requestId: req.id,
        event: 'validation_error',
        errors: errors.array()
      });
      return res.status(400).json({ 
        error: 'Invalid parameters',
        requestId: req.id 
      });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    logger.info({
      requestId: req.id,
      event: 'users_fetched',
      limit,
      offset
    });

    // Return minimal user data (no email unless specifically authorized)
    res.json({
      data: [
        { id: 1, name: 'Alice' },
        { id: 2, name: 'Bob' },
      ],
      pagination: {
        limit,
        offset,
        total: 2
      },
      requestId: req.id
    });
  }
);

// ============================================
// ERROR HANDLING
// ============================================

/**
 * 404 Handler
 */
app.use((req, res) => {
  logger.warn({
    requestId: req.id,
    event: '404_not_found',
    path: req.path
  });
  res.status(404).json({ 
    error: 'Not Found',
    requestId: req.id 
  });
});

/**
 * Global Error Handler
 * Must be defined last
 */
app.use((err, req, res, next) => {
  const requestId = req.id;

  logger.error({
    requestId,
    event: 'unhandled_error',
    error: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined
  });

  // Don't expose internal error details to clients
  const statusCode = err.statusCode || 500;
  const response = {
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error'
      : err.message,
    requestId
  };

  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// Validate required environment variables
const requiredEnvVars = ['NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  logger.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

const server = app.listen(PORT, () => {
  logger.info({
    event: 'server_started',
    port: PORT,
    environment: NODE_ENV
  });
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

module.exports = app;

