## Fix #5: Input Validation (HIGH)

### Before
```javascript
// No validation - vulnerable to injection
app.post('/users', (req, res) => {
  const { name, email } = req.body;
  // Query database with unvalidated input
  db.query(`INSERT INTO users VALUES ('${name}', '${email}')`);
});
```

### After
```javascript
const { body, validationResult } = require('express-validator');

app.post('/users', [
  // Validate and sanitize inputs
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .escape(),
  body('email')
    .isEmail()
    .normalizeEmail(),
  body('age')
    .optional()
    .isInt({ min: 0, max: 150 })
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  const { name, email, age } = req.body;
  // Use parameterized query
  db.query('INSERT INTO users (name, email, age) VALUES (?, ?, ?)', 
    [name, email, age], (err, result) => {
      if (err) return res.status(500).json({ error: 'Database error' });
      res.json({ success: true, userId: result.insertId });
    });
});
```

