// This is how app.js SHOULD look

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const mongoSanitize = require('express-mongo-sanitize');
const https = require('https');
const fs = require('fs');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');

const app = express();

// ============================================
// Security Middleware - CRITICAL
// ============================================

// 1. Helmet for security headers
app.use(helmet());

// 2. Request size limits - DoS protection
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 3. CORS configuration - CSRF protection
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  optionsSuccessStatus: 200
}));

// 4. Rate limiting - DoS protection
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
});
app.use(limiter);

// Stricter limiter for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
});

// 5. Data sanitization - Injection attack prevention
app.use(mongoSanitize());

// 6. Logging
app.use(morgan('combined'));

// ============================================
// Environment Validation
// ============================================

const requiredEnvVars = ['NODE_ENV', 'ACCESS_TOKEN_SECRET'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

// ============================================
// Authentication Middleware
// ============================================

const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET, (err, user) => {
    if (err) {
      return res.status(403).json({ error: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
};

// ============================================
// Public Routes
// ============================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// ============================================
// Protected Routes
// ============================================

// Users endpoint - PROTECTED with authentication
// Returns filtered data (no sensitive PII)
app.get('/users', authenticateToken, (req, res) => {
  // In production, this should query a database with proper access control
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ============================================
// Error Handling Middleware
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler (MUST be last)
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    status: err.status || 500,
    timestamp: new Date().toISOString(),
    path: req.path,
  });

  const status = err.status || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(status).json({ error: message });
});

// ============================================
// Graceful Shutdown
// ============================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  process.exit(1);
});

process.on('uncaughtException', (error) => {
  console.error('Uncaught Exception:', error);
  process.exit(1);
});

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;

// Use HTTPS in production
if (process.env.NODE_ENV === 'production') {
  if (!process.env.SSL_KEY_PATH || !process.env.SSL_CERT_PATH) {
    throw new Error('SSL_KEY_PATH and SSL_CERT_PATH required in production');
  }

  const options = {
    key: fs.readFileSync(process.env.SSL_KEY_PATH),
    cert: fs.readFileSync(process.env.SSL_CERT_PATH)
  };

  https.createServer(options, app).listen(PORT, () => {
    console.log(`🔒 Secure server running on port ${PORT}`);
  });
} else {
  // HTTP only for development
  console.warn('⚠️  Running in HTTP mode - use HTTPS in production!');
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT}`);
  });
}

module.exports = app;

