// Secure Node.js Express Application
// Demonstrates security best practices

require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, validationResult } = require('express-validator');
const morgan = require('morgan');

const app = express();
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============ SECURITY MIDDLEWARE ============

// 1. Security headers
app.use(helmet());

// 2. CORS configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// 4. Request size limits
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));

// 5. Request logging
app.use(morgan(NODE_ENV === 'production' ? 'combined' : 'dev'));

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

app.get('/users', (req, res) => {
  // In a real application, validate query parameters
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Example POST endpoint with input validation
app.post('/users', [
  body('name')
    .trim()
    .isLength({ min: 1, max: 100 })
    .withMessage('Name must be between 1 and 100 characters'),
  body('email')
    .isEmail()
    .normalizeEmail()
    .withMessage('Must be a valid email address')
], (req, res) => {
  // Check for validation errors
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }

  // Validated data is in req.body
  const { name, email } = req.body;

  // In a real app, save to database with parameterized queries
  res.status(201).json({
    id: 3,
    name,
    email,
    message: 'User created successfully'
  });
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    message: 'The requested resource does not exist',
    status: 404
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const status = err.status || 500;
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  // Log the error (in production, log to external service)
  console.error(`[${new Date().toISOString()}] Error:`, {
    status,
    message: err.message,
    method: req.method,
    path: req.path,
    stack: NODE_ENV === 'production' ? undefined : err.stack
  });

  res.status(status).json({
    error: 'Error',
    message,
    status
  });
});

// ============ SERVER ============

app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} (${NODE_ENV})`);
});

module.exports = app;

# Quick Security Reference for Node.js/Express

## 🔴 CRITICAL - Do This First

### 1. Never Commit Secrets
```bash
# ❌ BAD
git add .env
git add config.js  # with passwords

# ✅ GOOD
echo ".env*" >> .gitignore
echo "config.js" >> .gitignore
```

### 2. Always Use Environment Variables
```javascript
// ❌ BAD
const password = 'mySecretPassword123';

// ✅ GOOD
const password = process.env.DB_PASSWORD;
```

### 3. Use HTTPS in Production
```javascript
// ✅ GOOD
if (process.env.NODE_ENV === 'production') {
  https.createServer(options, app).listen(PORT);
} else {
  app.listen(PORT);
}
```

---

## 🔒 Security Best Practices

### Dependency Security
```bash
# Check for vulnerabilities
npm audit

# Fix vulnerabilities
npm audit fix

# Check outdated packages
npm outdated
```

### Input Validation
```javascript
// ✅ GOOD
const { body, validationResult } = require('express-validator');

app.post('/data', [
  body('email').isEmail(),
  body('age').isInt({ min: 0, max: 150 }),
], (req, res) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) return res.status(400).json({ errors: errors.array() });
  // Process validated data
});

// ❌ BAD - No validation
app.post('/data', (req, res) => {
  // Directly use req.body without validation
});
```

### SQL Injection Prevention
```javascript
// ❌ BAD - String concatenation (SQL Injection!)
db.query('SELECT * FROM users WHERE id = ' + req.body.id);

// ✅ GOOD - Parameterized queries
db.query('SELECT * FROM users WHERE id = ?', [req.body.id]);

// ✅ GOOD - ORM (Sequelize, TypeORM, Prisma)
User.findByPk(req.body.id);
```

### XSS Prevention
```javascript
// ❌ BAD - HTML in response
res.send('<p>' + userInput + '</p>');

// ✅ GOOD - Use template escaping
res.render('page', { content: userInput }); // Auto-escaped in EJS, Pug, etc.

// ✅ GOOD - JSON responses
res.json({ content: userInput }); // JSON is safe by default
```

### Security Headers
```javascript
const helmet = require('helmet');

// ✅ GOOD - Install helmet
app.use(helmet());

// This sets multiple security headers:
// X-Content-Type-Options: nosniff
// X-Frame-Options: DENY
// X-XSS-Protection: 1; mode=block
// Strict-Transport-Security: max-age=...
// Content-Security-Policy: default-src 'self'
```

### Rate Limiting
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // limit each IP to 100 requests per windowMs
});

app.use(limiter); // ✅ GOOD - Apply to all routes

// Or specific routes
app.post('/login', limiter, (req, res) => {
  // Login logic
});
```

### CORS Configuration
```javascript
const cors = require('cors');

// ❌ BAD - Allow all origins
app.use(cors()); // Only in development!

// ✅ GOOD - Restrict origins
app.use(cors({
  origin: 'https://yourdomain.com',
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));
```

### Error Handling
```javascript
// ❌ BAD - Expose errors to users
app.get('/data', (req, res) => {
  try {
    riskyOperation();
  } catch (err) {
    res.json({ error: err.stack }); // ❌ Exposes internal details!
  }
});

// ✅ GOOD - Generic error messages in production
app.use((err, req, res, next) => {
  console.error(err); // Log internally

  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(500).json({ error: message });
});
```

### Authentication
```javascript
// ✅ GOOD - Use secure passwords (bcrypt)
const bcrypt = require('bcrypt');

// When creating user
const hashedPassword = await bcrypt.hash(password, 10);
await db.users.create({ email, passwordHash: hashedPassword });

// When authenticating
const user = await db.users.findOne({ email });
const valid = await bcrypt.compare(password, user.passwordHash);

// ❌ BAD - Storing plain text passwords
db.users.create({ email, password }); // NEVER!
```

### Request Size Limits
```javascript
// ✅ GOOD - Prevent large payload DoS
app.use(express.json({ limit: '10mb' }));
app.use(express.urlencoded({ limit: '10mb', extended: true }));
```

### Logging (Security Events)
```javascript
const morgan = require('morgan');

// ✅ GOOD - Log all requests
app.use(morgan('combined'));

// ✅ GOOD - Log security events
function logSecurityEvent(event, details) {
  console.log(`[SECURITY] ${new Date().toISOString()}: ${event}`, details);
  // In production: send to SIEM
}

// Example usage
app.post('/login', (req, res) => {
  try {
    // authenticate...
    logSecurityEvent('LOGIN_SUCCESS', { user: email, ip: req.ip });
  } catch (err) {
    logSecurityEvent('LOGIN_FAILED', { email, ip: req.ip, reason: err.message });
  }
});
```

---

## 🚫 Common Vulnerabilities to Avoid

| Vulnerability | Example | Solution |
|---|---|---|
| SQL Injection | `SELECT * FROM users WHERE id = ${id}` | Use parameterized queries |
| XSS | `res.send('<p>' + input + '</p>')` | Use template escaping or JSON |
| CSRF | No token validation on state-changing requests | Use CSRF tokens (csrfProtection middleware) |
| Weak Authentication | Storing plain text passwords | Use bcrypt/Argon2 + salting |
| Missing Headers | No security headers sent | Use helmet.js |
| No Rate Limiting | Unlimited requests allowed | Use express-rate-limit |
| Exposed Secrets | API keys in code | Use environment variables |
| Unvalidated Input | Direct use of req.body | Use express-validator |
| Broken Access Control | No permission checks | Implement proper RBAC |
| Log Injection | User input in logs | Sanitize log inputs |

