// SECURE VERSION - Best practices applied
// This demonstrates how to harden the application against common vulnerabilities

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();

// ============================================
// 1. SECURITY HEADERS - Helmet middleware
// ============================================
app.use(helmet());

// ============================================
// 2. CORS - Restrict cross-origin access
// ============================================
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
}));

// ============================================
// 3. REQUEST LOGGING - Morgan middleware
// ============================================
app.use(morgan(process.env.NODE_ENV === 'production' ? 'combined' : 'dev'));

// ============================================
// 4. RATE LIMITING - Prevent abuse
// ============================================
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 10, // Stricter limit for sensitive endpoints
});

app.use(limiter);

// ============================================
// 5. AUTHENTICATION MIDDLEWARE
// ============================================
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ 
      error: 'Access token required',
      code: 'AUTH_REQUIRED'
    });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'dev-secret', (err, user) => {
    if (err) {
      return res.status(403).json({ 
        error: 'Invalid or expired token',
        code: 'AUTH_FAILED'
      });
    }
    req.user = user;
    next();
  });
};

// ============================================
// 6. INPUT VALIDATION
// ============================================
const validateUserQuery = [
  query('page')
    .optional()
    .isInt({ min: 1 })
    .toInt()
    .withMessage('Page must be a positive integer'),
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt()
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .isLength({ max: 100 })
    .withMessage('Search query cannot exceed 100 characters')
];

// ============================================
// 7. ENDPOINTS
// ============================================

// Health check (public, for monitoring)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Users endpoint (protected, validated)
app.get('/users', 
  authenticateToken,
  strictLimiter, // Stricter rate limiting for this endpoint
  validateUserQuery,
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Validation failed',
        details: errors.array() 
      });
    }

    const { page = 1, limit = 10, search } = req.query;

    // Mock user data (in production, query database with parameterized queries)
    let users = [
      { id: 1, name: 'Alice' }, // Removed email from response
      { id: 2, name: 'Bob' }
    ];

    // Safe search (in production, use parameterized queries)
    if (search) {
      users = users.filter(u => 
        u.name.toLowerCase().includes(search.toLowerCase())
      );
    }

    // Pagination
    const total = users.length;
    const startIdx = (page - 1) * limit;
    const paginatedUsers = users.slice(startIdx, startIdx + limit);

    res.json({
      data: paginatedUsers,
      pagination: {
        page,
        limit,
        total,
        totalPages: Math.ceil(total / limit)
      }
    });
  }
);

// ============================================
// 8. GLOBAL ERROR HANDLING
// ============================================
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    code: err.code,
    timestamp: new Date().toISOString(),
    path: req.path
    // Don't log sensitive data
  });

  // Don't expose error stack trace to client
  const statusCode = err.statusCode || 500;
  const response = {
    error: 'Internal Server Error',
    code: 'INTERNAL_ERROR'
  };

  // Only expose detailed errors in development
  if (process.env.NODE_ENV === 'development') {
    response.details = err.message;
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============================================
// 9. ENFORCE HTTPS IN PRODUCTION
// ============================================
if (process.env.NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      return res.redirect(301, `https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ============================================
// 10. 404 HANDLER
// ============================================
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    code: 'ROUTE_NOT_FOUND',
    path: req.path
  });
});

// ============================================
// 11. SERVER STARTUP
// ============================================
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

