// CORS configuration - restrict to specific origins
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Rate limiting - prevent brute force attacks
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

app.use(limiter);

// Body parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// ============ AUTHENTICATION MIDDLEWARE ============
const authMiddleware = (req, res, next) => {
  try {
    const token = req.headers.authorization?.split(' ')[1];

    if (!token) {
      return res.status(401).json({ error: 'Missing authorization token' });
    }

    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ============ ROUTES ============

// Health check endpoint (no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    node_env: process.env.NODE_ENV 
  });
});

// Protected users endpoint with input validation
app.get('/users', 
  authMiddleware,
  query('id').optional().isInt().toInt(),
  query('name').optional().isString().trim().escape(),
  (req, res) => {
    // Validate input
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply filters if provided
    let filteredUsers = users;
    if (req.query.id) {
      filteredUsers = users.filter(u => u.id === req.query.id);
    }
    if (req.query.name) {
      filteredUsers = filteredUsers.filter(u => 
        u.name.toLowerCase().includes(req.query.name.toLowerCase())
      );
    }

    res.json(filteredUsers);
  }
);

// Login endpoint to get JWT token
app.post('/login', express.json(), (req, res) => {
  // WARNING: This is a simplified example. Use proper password hashing in production!
  const user = {
    id: 1,
    name: 'Admin',
    email: 'admin@example.com'
  };

  const token = jwt.sign(user, process.env.JWT_SECRET, { expiresIn: '1h' });
  res.json({ token });
});

// ============ ERROR HANDLING ============
app.use((req, res, next) => {
  res.status(404).json({ error: 'Not found' });
});

app.use((err, req, res, next) => {
  console.error('Error:', err);

  // Don't leak error details in production
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error'
    : err.message;

  res.status(err.status || 500).json({ error: message });
});

// ============ SERVER STARTUP ============
const PORT = process.env.PORT || 3000;

if (process.env.NODE_ENV === 'production' && process.env.HTTPS_KEY && process.env.HTTPS_CERT) {
  // Use HTTPS in production
  const options = {
    key: fs.readFileSync(process.env.HTTPS_KEY),
    cert: fs.readFileSync(process.env.HTTPS_CERT)
  };

  https.createServer(options, app).listen(PORT, () => {
    console.log(`Secure server running on port ${PORT}`);
  });
} else {
  // HTTP for development
  app.listen(PORT, () => {
    console.log(`Server running on port ${PORT} (${process.env.NODE_ENV || 'development'})`);
  });
}

module.exports = app;

