// SECURE_APP_EXAMPLE.js
// This is a hardened version of app.js with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
const jwt = require('jsonwebtoken');

const app = express();
require('dotenv').config();

// ============================================================================
// SECURITY MIDDLEWARE
// ============================================================================

// 1. Helmet - Set various HTTP headers for security
app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
    },
  },
  referrerPolicy: { policy: 'strict-origin-when-cross-origin' },
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
}));

// 2. CORS - Configure Cross-Origin Resource Sharing
const allowedOrigins = (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(',');
app.use(cors({
  origin: (origin, callback) => {
    if (!origin || allowedOrigins.includes(origin)) {
      callback(null, true);
    } else {
      callback(new Error('Not allowed by CORS'));
    }
  },
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  maxAge: 3600,
  allowedHeaders: ['Content-Type', 'Authorization'],
}));

// 3. Request logging
app.use(morgan('combined', {
  skip: (req, res) => res.statusCode < 400, // Only log errors
}));

// 4. Body parser with size limits
app.use(express.json({ limit: '10kb' })); // Prevent large payloads
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 5. Rate limiting - Prevent brute force and DoS
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
  message: 'Too many requests from this IP, please try again later.',
  skip: (req) => req.path === '/health', // Don't rate limit health checks
});
app.use(limiter);

// Stricter rate limit for auth endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // 5 requests per 15 minutes for login
  message: 'Too many login attempts, please try again later.',
});

// ============================================================================
// AUTHENTICATION & AUTHORIZATION
// ============================================================================

/**
 * Verify JWT token
 * @param {string} token - JWT token
 * @returns {object} Decoded token payload
 * @throws {Error} If token is invalid
 */
const verifyToken = (token) => {
  try {
    return jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key');
  } catch (err) {
    throw new Error('Invalid or expired token');
  }
};

/**
 * Middleware to verify JWT token from Authorization header
 */
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({
      error: 'Access token required',
      code: 'MISSING_TOKEN',
    });
  }

  try {
    const decoded = verifyToken(token);
    req.userId = decoded.userId;
    req.userRole = decoded.role || 'user';
    next();
  } catch (err) {
    return res.status(403).json({
      error: 'Invalid or expired token',
      code: 'INVALID_TOKEN',
    });
  }
};

/**
 * Middleware to check user role/authorization
 */
const authorize = (requiredRoles = []) => {
  return (req, res, next) => {
    if (!requiredRoles.includes(req.userRole)) {
      return res.status(403).json({
        error: 'Insufficient permissions',
        code: 'FORBIDDEN',
      });
    }
    next();
  };
};

// ============================================================================
// INPUT VALIDATION
// ============================================================================

/**
 * Middleware to handle validation errors
 */
const handleValidationErrors = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({
      error: 'Validation failed',
      details: errors.array().map(err => ({
        field: err.param,
        message: err.msg,
      })),
    });
  }
  next();
};

// ============================================================================
// ROUTES
// ============================================================================

/**
 * Health check endpoint (public)
 * GET /health
 */
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime(),
  });
});

/**
 * Login endpoint - Generate JWT token
 * POST /login
 * Body: { username: string, password: string }
 */
app.post('/login', authLimiter, (req, res) => {
  const { username, password } = req.body;

  // TODO: Validate credentials against database
  // In production, use bcrypt to compare hashed passwords
  if (!username || !password) {
    return res.status(400).json({
      error: 'Username and password required',
      code: 'INVALID_CREDENTIALS',
    });
  }

  // SECURITY: Never log passwords
  console.log(`Login attempt for user: ${username}`);

  // Dummy validation - replace with actual database lookup
  if (username === 'demo' && password === 'password') {
    const token = jwt.sign(
      { userId: 1, username, role: 'user' },
      process.env.JWT_SECRET || 'your-secret-key',
      { expiresIn: '1h' }
    );

    return res.json({
      message: 'Login successful',
      token,
      expiresIn: 3600,
    });
  }

  // Generic error message to prevent user enumeration
  res.status(401).json({
    error: 'Invalid credentials',
    code: 'INVALID_CREDENTIALS',
  });
});

/**
 * Get users endpoint (protected)
 * GET /users?limit=10&offset=0
 */
app.get('/users',
  authenticateToken,
  authorize(['user', 'admin']),
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  handleValidationErrors,
  (req, res) => {
    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    // SECURITY: Only return non-sensitive fields
    // Never return passwords, emails (unless authorized), etc.
    const users = [
      { id: 1, name: 'Alice', role: 'admin' },
      { id: 2, name: 'Bob', role: 'user' },
      { id: 3, name: 'Charlie', role: 'user' },
    ];

    // Implement pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset,
    });
  }
);

/**
 * Get single user endpoint (protected)
 * GET /users/:id
 */
app.get('/users/:id',
  authenticateToken,
  query('id').isInt(),
  handleValidationErrors,
  (req, res) => {
    const userId = parseInt(req.params.id, 10);

    // SECURITY: Check authorization - users can only see their own data
    if (req.userRole !== 'admin' && req.userId !== userId) {
      return res.status(403).json({
        error: 'You do not have permission to access this resource',
        code: 'FORBIDDEN',
      });
    }

    // Dummy data - fetch from database in production
    const user = { id: userId, name: 'Alice' };

    res.json(user);
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

/**
 * 404 Not Found handler
 */
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path,
    method: req.method,
    code: 'NOT_FOUND',
  });
});

/**
 * Global error handler - MUST be last
 */
app.use((err, req, res, next) => {
  const isDevelopment = process.env.NODE_ENV === 'development';
  const statusCode = err.statusCode || err.status || 500;

  // SECURITY: Log errors but don't expose stack traces to clients
  console.error({
    timestamp: new Date().toISOString(),
    statusCode,
    message: err.message,
    path: req.path,
    method: req.method,
    userId: req.userId || 'anonymous',
    ...(isDevelopment && { stack: err.stack }),
  });

  res.status(statusCode).json({
    error: err.message || 'Internal Server Error',
    code: err.code || 'INTERNAL_ERROR',
    ...(isDevelopment && { stack: err.stack }),
  });
});

// ============================================================================
// UNHANDLED EXCEPTION HANDLERS
// ============================================================================

process.on('unhandledRejection', (reason, promise) => {
  console.error('Unhandled Rejection at:', promise, 'reason:', reason);
  // In production, this should trigger an alert/notification
  process.exit(1);
});

process.on('uncaughtException', (err) => {
  console.error('Uncaught Exception:', err);
  // In production, gracefully shutdown
  process.exit(1);
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const server = app.listen(PORT, () => {
  console.log(`✓ Server running on port ${PORT}`);
  console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
  console.log(`✓ Node.js version: ${process.version}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;

