// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const winston = require('winston');
require('dotenv').config();

// ============================================================================
// LOGGING SETUP
// ============================================================================
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'user-api' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' })
  ]
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple()
  }));
}

// ============================================================================
// ENVIRONMENT VALIDATION
// ============================================================================
const requiredEnvVars = ['JWT_SECRET', 'NODE_ENV'];
requiredEnvVars.forEach(envVar => {
  if (!process.env[envVar]) {
    throw new Error(`Missing required environment variable: ${envVar}`);
  }
});

// ============================================================================
// APPLICATION SETUP
// ============================================================================
const app = express();

// Middleware: Security headers
app.use(helmet());

// Middleware: CORS
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'OPTIONS'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// Middleware: Request logging
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent')
  });
  next();
});

// Middleware: Body parsing (minimal for this app)
app.use(express.json({ limit: '10kb' })); // Limit payload size

// Middleware: Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP',
  standardHeaders: true,
  legacyHeaders: false,
  handler: (req, res) => {
    logger.warn({ ip: req.ip, message: 'Rate limit exceeded' });
    res.status(429).json({ error: 'Too many requests' });
  }
});

app.use(limiter);

// ============================================================================
// AUTHENTICATION MIDDLEWARE
// ============================================================================
function verifyToken(req, res, next) {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    logger.warn({ ip: req.ip, path: req.path, message: 'No token provided' });
    return res.status(401).json({ error: 'No authorization token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    logger.info({ userId: decoded.id, action: 'Token verified' });
    next();
  } catch (err) {
    logger.warn({ ip: req.ip, message: 'Invalid token', error: err.message });
    return res.status(403).json({ error: 'Invalid or expired token' });
  }
}

// ============================================================================
// ROUTES
// ============================================================================

// Health check (no auth required, useful for monitoring)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Get users (requires authentication and validates input)
app.get('/users',
  verifyToken,
  query('limit').optional().isInt({ min: 1, max: 100 }).toInt(),
  query('offset').optional().isInt({ min: 0 }).toInt(),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      logger.warn({ errors: errors.array(), userId: req.user.id });
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = req.query.limit || 10;
    const offset = req.query.offset || 0;

    logger.info({
      userId: req.user.id,
      action: 'GET /users',
      limit,
      offset
    });

    // Mock data - replace with database query
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json({
      data: users.slice(offset, offset + limit),
      total: users.length,
      limit,
      offset
    });
  }
);

// ============================================================================
// ERROR HANDLING
// ============================================================================

// 404 handler
app.use((req, res) => {
  logger.warn({ path: req.path, method: req.method, message: 'Route not found' });
  res.status(404).json({ error: 'Route not found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method
  });

  // Don't expose error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production'
    ? 'Internal server error'
    : err.message;

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ============================================================================
// SERVER STARTUP
// ============================================================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

app.listen(PORT, HOST, () => {
  logger.info({
    message: 'Server started',
    port: PORT,
    host: HOST,
    environment: process.env.NODE_ENV
  });
});

module.exports = app;

// Security Tests Examples
// Use this with Jest and Supertest

const request = require('supertest');
const app = require('./app.secure');
const jwt = require('jsonwebtoken');

describe('Security Tests', () => {
  let validToken;
  let invalidToken = 'invalid.token.here';

  beforeAll(() => {
    // Generate a valid token for testing
    validToken = jwt.sign(
      { id: 1, email: 'test@example.com' },
      process.env.JWT_SECRET,
      { expiresIn: '1h' }
    );
  });

  describe('Authentication Tests', () => {
    test('GET /health should not require authentication', async () => {
      const res = await request(app).get('/health');
      expect(res.statusCode).toBe(200);
      expect(res.body).toHaveProperty('status', 'ok');
    });

    test('GET /users should require authentication', async () => {
      const res = await request(app).get('/users');
      expect(res.statusCode).toBe(401);
      expect(res.body).toHaveProperty('error');
    });

    test('GET /users with valid token should succeed', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${validToken}`);
      expect(res.statusCode).toBe(200);
      expect(res.body).toHaveProperty('data');
    });

    test('GET /users with invalid token should fail', async () => {
      const res = await request(app)
        .get('/users')
        .set('Authorization', `Bearer ${invalidToken}`);
      expect(res.statusCode).toBe(403);
      expect(res.body).toHaveProperty('error');
    });

