  // CORS not configured = open to all origins
  res.json([...]);
});
```

**Problems:**
- Requests from any origin accepted
- CSRF attacks possible
- Credentials can be leaked

**✅ AFTER**
```javascript
const cors = require('cors');

app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
}));

// Or specific CORS for endpoints
app.get('/users', cors({
  origin: 'https://example.com'
}), (req, res) => {
  res.json([...]);
});
```

---

### Issue 8: NO LOGGING/MONITORING

**❌ BEFORE**
```javascript
app.get('/users', (req, res) => {
  // No logging
  // Security incidents not tracked
  console.log('Server running on port 3000');
  res.json([...]);
});
```

**Problems:**
- No audit trail
- Can't detect attacks
- No visibility into issues

**✅ AFTER**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// HTTP request logging
app.use(morgan('combined', {
  stream: { write: (msg) => logger.info(msg) }
}));

// Structured logging
const logger = winston.createLogger({
  format: winston.format.json(),
  transports: [
    new winston.transports.File({ filename: 'security.log' }),
    new winston.transports.File({ filename: 'error.log', level: 'error' })
  ]
});

app.get('/users', (req, res) => {
  logger.info(`User list accessed by ${req.user.id}`, {
    userId: req.user.id,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });
  res.json([...]);
});
```

---

### Issue 9: HARDCODED CONFIGURATION

**❌ BEFORE**
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

**Problems:**
- Hard to configure for different environments
- No NODE_ENV checks
- Security settings not configurable

**✅ AFTER**
```javascript
require('dotenv').config();

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const app = express();

if (NODE_ENV === 'production') {
  // Production-specific settings
  app.set('trust proxy', 1);
  app.use(helmet.strictTransportSecurity({
    maxAge: 31536000,
    includeSubDomains: true,
    preload: true
  }));
}

if (NODE_ENV === 'development') {
  // Development-specific settings
  app.use(morgan('dev'));
}

app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});
```

---

## Summary: Security Improvements

| Category | Before | After | Status |
|----------|--------|-------|--------|
| Credentials | Exposed in .env.test | In .env (gitignored) + secret management | ✅ Fixed |
| Headers | None | Helmet.js + CSP | ✅ Fixed |
| Auth | None | JWT + middleware | ✅ Fixed |
| Input Validation | None | express-validator | ✅ Fixed |
| Rate Limiting | None | express-rate-limit | ✅ Fixed |
| CORS | Unrestricted | Configured | ✅ Fixed |
| Error Handling | Unhandled | Try-catch + error handler | ✅ Fixed |
| Logging | console.log | Winston + Morgan | ✅ Fixed |
| Configuration | Hardcoded | dotenv | ✅ Fixed |

---

**All critical vulnerabilities have been addressed!**

