// Secure Express application with security best practices applied
// Reference implementation for security improvements

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
require('dotenv').config({ path: '.env.local' });

const app = express();

// ===== SECURITY MIDDLEWARE =====

// 1. Use Helmet to set security headers
app.use(helmet());

// 2. Configure CORS properly
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  optionsSuccessStatus: 200,
  maxAge: 86400 // 24 hours
};
app.use(cors(corsOptions));

// 3. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: false }));

// 4. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in the `RateLimit-*` headers
  legacyHeaders: false, // Disable the `X-RateLimit-*` headers
  store: new (require('rate-limit-memory-store'))(), // Use memory store for simplicity
  skip: (req) => {
    // Don't apply rate limiting to health checks
    return req.path === '/health';
  }
});
app.use(limiter);

// 5. Request logging middleware (security-focused)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip
    });
  });
  next();
});

// ===== AUTHENTICATION MIDDLEWARE =====

// Simple token validation (replace with JWT or OAuth in production)
const authenticateToken = (req, res, next) => {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ error: 'Access token required' });
  }

  // In production, verify JWT here
  if (token === 'VALID_TOKEN_FOR_TESTING') {
    next();
  } else {
    res.status(403).json({ error: 'Invalid or expired token' });
  }
};

// ===== ROUTES =====

// Health check endpoint (no auth required, but rate limited separately)
app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    uptime: process.uptime()
  });
});

// Protected endpoint with input validation
app.get('/users',
  // Validate query parameters
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('offset')
    .optional()
    .isInt({ min: 0 })
    .withMessage('Offset must be a positive integer'),
  query('id')
    .optional()
    .isInt()
    .withMessage('ID must be an integer'),
  // Authentication
  authenticateToken,
  // Handler
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const limit = Math.min(parseInt(req.query.limit) || 10, 100);
    const offset = parseInt(req.query.offset) || 0;

    // Mock data - in production, fetch from database
    const allUsers = [
      { id: 1, name: 'Alice' }, // No email exposure
      { id: 2, name: 'Bob' },
      { id: 3, name: 'Charlie' }
    ];

    // Filter by ID if provided
    let users = allUsers;
    if (req.query.id) {
      users = users.filter(u => u.id === parseInt(req.query.id));
    }

    // Apply pagination
    const paginatedUsers = users.slice(offset, offset + limit);

    res.json({
      data: paginatedUsers,
      total: users.length,
      limit,
      offset,
      hasMore: offset + limit < users.length
    });
  }
);

// ===== ERROR HANDLING =====

// 404 handler
app.use((req, res) => {
  res.status(404).json({
    error: 'Not Found',
    path: req.path
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: process.env.NODE_ENV === 'development' ? err.stack : undefined,
    path: req.path,
    method: req.method,
    ip: req.ip,
    timestamp: new Date().toISOString()
  });

