╠════════════════════════════════════════╣
║  Environment: ${NODE_ENV.padEnd(28)}║
║  Port: ${String(PORT).padEnd(36)}║
║  Status: ✅ Running                     ║
╚════════════════════════════════════════╝
  `);
});

// Graceful shutdown
