// Secure version of the application with recommended security practices

const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// ============================================
// SECURITY MIDDLEWARE
// ============================================

// 1. Helmet - Set security headers
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});
app.use(limiter);

// Apply stricter rate limiting to sensitive endpoints
const strictLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  message: 'Too many attempts, please try again later.'
});

// 4. Request Logging
app.use(morgan('combined'));

// 5. Body Parser with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// ============================================
// ROUTES
// ============================================

// Health check endpoint (no sensitive data)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString() 
  });
});

// Users endpoint - returns only necessary data, no sensitive info
app.get('/users', (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice' },
      { id: 2, name: 'Bob' },
    ]);
  } catch (error) {
    next(error);
  }
});

// Example: Protected endpoint with input validation
app.post('/users', strictLimiter, [
  body('name')
    .trim()
    .notEmpty().withMessage('Name is required')
    .isLength({ min: 2, max: 50 }).withMessage('Name must be between 2 and 50 characters')
    .escape(),
  body('email')
    .isEmail().withMessage('Valid email is required')
    .normalizeEmail()
], (req, res, next) => {
  try {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // TODO: Add authentication check here
    // TODO: Save to database

    res.status(201).json({
      id: 3,
      name: req.body.name,
      message: 'User created successfully'
    });
  } catch (error) {
    next(error);
  }
});

// ============================================
// ERROR HANDLING
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  const status = err.status || err.statusCode || 500;

  console.error({
    timestamp: new Date().toISOString(),
    error: err.message,
    status: status,
    path: req.path,
    method: req.method
  });

  res.status(status).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message,
    // Only include stack trace in development
    ...(process.env.NODE_ENV !== 'production' && { stack: err.stack })
  });
});

// ============================================
// SERVER STARTUP
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
  console.log(`Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;

# Before & After Comparison

## Current Application (app.js)

```javascript
const express = require('express');
const app = express();

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

app.listen(3000, () => {
  console.log('Server running on port 3000');
});

module.exports = app;
```

### Issues:
- ❌ No security headers
- ❌ No rate limiting
- ❌ No CORS handling
- ❌ No input validation
- ❌ No error handling
- ❌ Exposes sensitive data (emails)
- ❌ Hardcoded port
- ❌ No logging
- ❌ No request size limits

---

## Secure Application (app.secure.js)

```javascript
const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const morgan = require('morgan');
const { body, validationResult } = require('express-validator');
require('dotenv').config();

const app = express();

// Security Middleware
app.use(helmet());                    // ✓ Security headers
app.use(cors({...}));                // ✓ CORS protection
app.use(rateLimit({...}));           // ✓ Rate limiting
app.use(morgan('combined'));         // ✓ Request logging
app.use(express.json({limit:'10kb'})); // ✓ Request limits

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

app.get('/users', (req, res) => {
  try {
    res.json([
      { id: 1, name: 'Alice' },  // ✓ No sensitive data
      { id: 2, name: 'Bob' },
    ]);
  } catch (error) {
    next(error);
  }
});

// Error Handling
app.use((err, req, res, next) => {
  // ✓ Proper error handling
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => console.log(`Server running on port ${PORT}`));

module.exports = app;
```

### Improvements:
- ✅ Security headers via Helmet
- ✅ Rate limiting implemented
- ✅ CORS properly configured
- ✅ Request logging enabled
- ✅ Request size limits
- ✅ Sensitive data removed from responses
- ✅ Environment configuration
- ✅ Comprehensive error handling
- ✅ Try-catch blocks for error safety

---

## Security Headers Comparison

### Before
```
No security headers sent
Vulnerable to: XSS, Clickjacking, MIME sniffing, CSRF
```

### After
```
Content-Security-Policy: default-src 'self'
X-Frame-Options: DENY
X-Content-Type-Options: nosniff
X-XSS-Protection: 1; mode=block
Strict-Transport-Security: max-age=31536000; includeSubDomains
Referrer-Policy: no-referrer
```

---

## Rate Limiting Comparison

### Before
```
No rate limiting
- Unlimited requests allowed per IP
- Vulnerable to DoS attacks
- Vulnerable to brute force attacks
```

### After
```
General endpoints: 100 requests per 15 minutes
Sensitive endpoints: 5 requests per 15 minutes

Benefits:
✅ DoS protection
✅ Brute force protection
✅ Fair resource allocation
✅ IP tracking and blocking
```

---

## Error Handling Comparison

### Before - Unsafe
```javascript
app.get('/users', (req, res) => {
  res.json([...]);
  // No error handling - uncaught errors crash the process
});

// Returns full stack trace to client (exposes internals)
```

### After - Safe
```javascript
app.get('/users', (req, res, next) => {
  try {
    res.json([...]);
  } catch (error) {
    next(error);
  }
});

app.use((err, req, res, next) => {
  // Only show error message in production
  res.status(err.status || 500).json({
    error: process.env.NODE_ENV === 'production' 
      ? 'Internal Server Error' 
      : err.message
  });
});
```

---

## Input Validation Comparison

### Before - No Validation
```javascript
app.post('/users', (req, res) => {
  // No validation - accepts anything
  const { name, email } = req.body;

  // Vulnerable to:
  // - Injection attacks
  // - Type confusion
  // - Malformed data
  // - Buffer overflow attacks
});
```

### After - With Validation
```javascript
app.post('/users', [
  body('name')
    .trim()
    .notEmpty().withMessage('Name required')
    .isLength({ min: 2, max: 50 })
    .escape(),
  body('email')
    .isEmail()
    .normalizeEmail()
], (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ errors: errors.array() });
  }
  // Validated data is safe to process
});
```

---

## Data Exposure Comparison

### Before - Exposes PII
```json
GET /users
{
  "id": 1,
  "name": "Alice",
  "email": "alice@example.com"    ← PII exposed
}
```

### After - Privacy Protected
```json
GET /users
{
  "id": 1,
  "name": "Alice"                 ← Only necessary data
}
```

---

## CORS Comparison

### Before - Open to All
```
No CORS configuration
Allows requests from ANY origin
Any domain can access your API

Vulnerable to:
- Cross-origin data theft
- Malicious requests
```

### After - Restricted
```javascript
app.use(cors({
  origin: ['https://trusted-domain.com'],
  credentials: true,
  methods: ['GET', 'POST'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

Only whitelisted origins can access
Specific methods allowed
```

---

## Environment Configuration

### Before - Hardcoded
```javascript
app.listen(3000, () => {
  console.log('Server running on port 3000');
});
```

### After - Configurable
```javascript
const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';
const NODE_ENV = process.env.NODE_ENV || 'development';

app.listen(PORT, HOST, () => {
  console.log(`Server running on ${HOST}:${PORT}`);
