    res.json(users);
  } catch (error) {
    res.status(500).json({ error: 'Failed to fetch users' });
  }
});

// Option 2: Load from configuration
const DEFAULT_USERS = JSON.parse(process.env.DEFAULT_USERS || '[]');
app.get('/users', (req, res) => {
  res.json(DEFAULT_USERS);
});
