```javascript
require('dotenv').config();
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// CONFIGURATION FROM ENVIRONMENT VARIABLES
// ============================================

const config = {
  // Server configuration
  NODE_ENV: process.env.NODE_ENV || 'development',
  PORT: parseInt(process.env.PORT || '3000', 10),
  HOST: process.env.HOST || 'localhost',

  // Logging configuration
  LOG_LEVEL: process.env.LOG_LEVEL || 'info',

  // Request configuration
  REQUEST_TIMEOUT: parseInt(process.env.REQUEST_TIMEOUT || '30000', 10),
  BODY_SIZE_LIMIT: process.env.BODY_SIZE_LIMIT || '10kb',

  // CORS configuration
  ALLOWED_ORIGINS: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),

  // Rate limiting configuration
  RATE_LIMIT_WINDOW_MS: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 minutes
  RATE_LIMIT_MAX: parseInt(process.env.RATE_LIMIT_MAX || '100', 10),

  // Security configuration
  JWT_SECRET: process.env.JWT_SECRET || 'dev-secret-key',
  SESSION_SECRET: process.env.SESSION_SECRET || 'dev-session-secret',

  // Data configuration
  DEFAULT_USERS: JSON.parse(process.env.DEFAULT_USERS || '[]'),
};

// ============================================
// VALIDATION
// ============================================

if (config.NODE_ENV === 'production') {
  if (!process.env.JWT_SECRET || process.env.JWT_SECRET === 'dev-secret-key') {
    throw new Error('JWT_SECRET must be set in production');
  }
  if (!process.env.SESSION_SECRET || process.env.SESSION_SECRET === 'dev-session-secret') {
    throw new Error('SESSION_SECRET must be set in production');
  }
}

// ============================================
// SECURITY MIDDLEWARE
// ============================================

app.use(helmet());
app.use(cors({
  origin: config.ALLOWED_ORIGINS,
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

const limiter = rateLimit({
  windowMs: config.RATE_LIMIT_WINDOW_MS,
  max: config.RATE_LIMIT_MAX,
  message: 'Too many requests, please try again later.'
});
app.use(limiter);

app.use(express.json({ limit: config.BODY_SIZE_LIMIT }));

// ============================================
// REQUEST TIMEOUT
// ============================================

app.use((req, res, next) => {
  req.setTimeout(config.REQUEST_TIMEOUT);
  res.setTimeout(config.REQUEST_TIMEOUT);
  next();
});

// ============================================
// LOGGING
// ============================================

const logger = {
  info: (msg) => console.log(`[${new Date().toISOString()}] INFO: ${msg}`),
  error: (msg) => console.error(`[${new Date().toISOString()}] ERROR: ${msg}`),
  warn: (msg) => console.warn(`[${new Date().toISOString()}] WARN: ${msg}`),
  debug: (msg) => {
    if (config.LOG_LEVEL === 'debug') {
      console.log(`[${new Date().toISOString()}] DEBUG: ${msg}`);
    }
  }
};

// ============================================
// ROUTES
// ============================================

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: config.NODE_ENV,
    uptime: process.uptime()
  });
});

app.get('/users',
  query('page').optional().isInt({ min: 1 }),
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Use users from environment or database
    const users = config.DEFAULT_USERS.length > 0
      ? config.DEFAULT_USERS
      : [
          { id: 1, name: 'Alice' },
          { id: 2, name: 'Bob' }
        ];

    res.json(users);
  }
);

// ============================================
// ERROR HANDLING
// ============================================

app.use((err, req, res, next) => {
  logger.error(`${err.message} - ${err.stack}`);
  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    ...(config.NODE_ENV !== 'production' && { details: err.message })
  });
});

app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// ============================================
// SERVER START
// ============================================

const server = app.listen(config.PORT, config.HOST, () => {
  logger.info(`🚀 Server starting...`);
  logger.info(`Environment: ${config.NODE_ENV}`);
  logger.info(`Listening on ${config.HOST}:${config.PORT}`);
  logger.info(`Log Level: ${config.LOG_LEVEL}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT signal received: closing HTTP server');
  server.close(() => {
    logger.info('HTTP server closed');
    process.exit(0);
  });
});

module.exports = app;
```

