// Secure version of app.js with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const morgan = require('morgan');
require('dotenv').config();

const app = express();
const NODE_ENV = process.env.NODE_ENV || 'development';
const PORT = process.env.PORT || 3000;

// ============================================
// Security Middleware
// ============================================

// 1. Add security headers with helmet
app.use(helmet());

// 2. Configure CORS
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  methods: ['GET', 'HEAD', 'OPTIONS'],
  credentials: true,
  maxAge: 3600,
  optionsSuccessStatus: 200
}));

// 3. Implement rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in RateLimit-* headers
  legacyHeaders: false // Disable X-RateLimit-* headers
});
app.use(limiter);

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Structured logging
app.use(morgan('combined'));

// 6. Production-specific settings
if (NODE_ENV === 'production') {
  app.disable('x-powered-by'); // Hide Express version
  app.set('trust proxy', 1); // Trust reverse proxy

  // Force HTTPS
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(301, `https://${req.header('host')}${req.url}`);
    }
    next();
  });
}

// ============================================
// Routes
// ============================================

// Health check endpoint - minimal info in production
app.get('/health', (req, res) => {
  if (NODE_ENV === 'production') {
    res.json({ status: 'ok' });
  } else {
    res.json({ 
      status: 'ok', 
      timestamp: new Date().toISOString(),
      environment: NODE_ENV
    });
  }
});

// Users endpoint with input validation
app.get('/users',
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .withMessage('Limit must be between 1 and 100'),
  query('search')
    .optional()
    .trim()
    .escape()
    .isLength({ max: 50 })
    .withMessage('Search term too long'),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Apply search filter if provided
    let result = users;
    if (req.query.search) {
      result = users.filter(u => 
        u.name.toLowerCase().includes(req.query.search.toLowerCase())
      );
    }

    res.json(result);
  }
);

// ============================================
// Error Handling
// ============================================

// 404 handler
app.use((req, res) => {
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err);

  if (NODE_ENV === 'production') {
    // Don't expose internal details in production
    res.status(err.status || 500).json({ 
      error: 'Internal Server Error' 
    });
  } else {
    // Expose details in development
    res.status(err.status || 500).json({ 
      error: err.message,
      stack: err.stack 
    });
  }
});

// ============================================
// Server Startup
// ============================================

app.listen(PORT, () => {
  console.log(`[${NODE_ENV.toUpperCase()}] Server running on port ${PORT}`);
});

module.exports = app;

