// Secure version of application
// This implementation includes security best practices

require('dotenv').config(); // Load from .env (not version controlled)
const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { body, param, validationResult } = require('express-validator');
const jwt = require('jsonwebtoken');
const morgan = require('morgan');
const https = require('https');
const fs = require('fs');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Set security HTTP headers
app.use(helmet());

// 2. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});
app.use(limiter);

// 3. CORS configuration
app.use(cors({
  origin: (process.env.ALLOWED_ORIGINS || 'http://localhost:3000').split(','),
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization']
}));

// 4. Body parsing with size limits
app.use(express.json({ limit: '10kb' }));
app.use(express.urlencoded({ limit: '10kb', extended: true }));

// 5. Request logging
app.use(morgan('combined'));

// ============ AUTHENTICATION MIDDLEWARE ============

function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader && authHeader.split(' ')[1]; // Bearer TOKEN

  if (!token) {
    return res.status(401).json({ message: 'Access token required' });
  }

  jwt.verify(token, process.env.ACCESS_TOKEN_SECRET || 'your-secret-key', (err, user) => {
    if (err) {
      return res.status(403).json({ message: 'Invalid or expired token' });
    }
    req.user = user;
    next();
  });
}

// ============ ROUTES ============

app.get('/health', (req, res) => {
  res.json({
    status: 'ok',
    timestamp: new Date().toISOString(),
    environment: process.env.NODE_ENV || 'development'
  });
});

// Protected route with authentication
app.get('/users', authenticateToken, (req, res) => {
  try {
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    // Validate response data
    const sanitizedUsers = users.map(user => ({
      id: user.id,
      name: user.name.substring(0, 255),
      email: user.email.toLowerCase()
    }));

    res.json(sanitizedUsers);
  } catch (error) {
    next(error);
  }
});

// Example of input validation
app.post('/users',
  authenticateToken,
  [
    body('name').trim().isLength({ min: 1, max: 255 }),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res, next) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    try {
      // Process validated input
      const newUser = {
        id: 3,
        name: req.body.name,
        email: req.body.email
      };
      res.status(201).json(newUser);
    } catch (error) {
      next(error);
    }
  }
);

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ message: 'Route not found' });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error('Error:', err);

  const statusCode = err.status || err.statusCode || 500;
  const response = {
    message: err.message || 'Internal server error'
  };

  // Only expose stack trace in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// ============ SERVER STARTUP ============

const port = process.env.PORT || 3000;
const env = process.env.NODE_ENV || 'development';

if (env === 'production' && process.env.HTTPS_KEY && process.env.HTTPS_CERT) {
  // Use HTTPS in production
  const options = {
    key: fs.readFileSync(process.env.HTTPS_KEY),
    cert: fs.readFileSync(process.env.HTTPS_CERT)
  };
  https.createServer(options, app).listen(port, () => {
    console.log(`Secure server running on port ${port} in ${env} mode`);
  });
} else {
  app.listen(port, () => {
    console.log(`Server running on port ${port} in ${env} mode`);
    if (env === 'production') {
      console.warn('⚠️  Warning: Running in production without HTTPS');
    }
  });
}

module.exports = app;

# Before & After: Security Comparison

## Code Comparison

### Issue #1: Hardcoded Secrets

**❌ BEFORE:**
```javascript
// .env.test (tracked in git)
DATABASE_URL=postgres://admin:CANARY-db-secret-7f3a@db.internal:5432/production
AWS_ACCESS_KEY_ID=AKIACANARY1234567890
```

**✅ AFTER:**
```javascript
