AWS_ACCESS_KEY_ID=AKIA${NEW_KEY}
```

```javascript
// app.js
const dbUrl = process.env.DATABASE_URL; // Load from environment
```

---

### Issue #2: No Authentication

**❌ BEFORE:**
```javascript
app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// ANYONE can access this! No authentication needed.
// curl http://localhost:3000/users
// Returns all user data instantly
```

**✅ AFTER:**
```javascript
app.get('/users', authenticateToken, (req, res) => {
  res.json([
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ]);
});

// Requires JWT token in Authorization header
// curl http://localhost:3000/users  // 401 Unauthorized
// curl -H "Authorization: Bearer token" http://localhost:3000/users  // 200 OK
```

---

### Issue #3: No Security Headers

**❌ BEFORE:**
```javascript
const app = express();
app.get('/health', ...);
// No security headers!
// Vulnerable to XSS, clickjacking, MIME sniffing
```

**✅ AFTER:**
```javascript
const helmet = require('helmet');

app.use(helmet());
// Automatically sets all security headers:
// - Content-Security-Policy
// - X-Frame-Options: DENY
// - X-Content-Type-Options: nosniff
// - Strict-Transport-Security
// - X-XSS-Protection
```

---

### Issue #4: No Rate Limiting

**❌ BEFORE:**
```javascript
app.get('/health', (req, res) => {
  res.json({ status: 'ok' });
});

// No rate limiting!
// Attacker can: 
// - Spam endpoint 1000x per second
// - DOS attack the server
// - Brute force other endpoints
```

**✅ AFTER:**
```javascript
const rateLimit = require('express-rate-limit');

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100 // Max 100 requests per IP per 15 min
});

app.use(limiter);

// Enforces:
// - Max 100 requests per IP per 15 minutes
// - Returns 429 Too Many Requests when exceeded
// - Protects against DOS and brute force
```

---

### Issue #5: No Input Validation

**❌ BEFORE:**
```javascript
app.post('/users', (req, res) => {
  const newUser = {
    id: 3,
    name: req.body.name,        // No validation!
    email: req.body.email       // Could be anything
  };
  res.status(201).json(newUser);
});

// Accepts invalid input:
// POST /users
// { "name": null, "email": "not-an-email" }
// 
// Could lead to:
// - SQL injection (if used in database queries)
// - XSS attacks
// - Data corruption
```

**✅ AFTER:**
```javascript
const { body, validationResult } = require('express-validator');

app.post('/users',
  [
    body('name').trim().isLength({ min: 1, max: 255 }),
    body('email').isEmail().normalizeEmail(),
  ],
  (req, res) => {
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ errors: errors.array() });
    }

    // Now we know data is valid
    const newUser = {
      id: 3,
      name: req.body.name,
      email: req.body.email
    };
    res.status(201).json(newUser);
  }
);

// Validates input:
// - Name: not empty, max 255 chars, trimmed
// - Email: valid email format, normalized
// - Returns 400 with error details if invalid
```

---

### Issue #6: No Error Handling

**❌ BEFORE:**
```javascript
app.get('/health', (req, res) => {
  throw new Error('Oops!');
});

// What happens?
// Server crashes and returns:
// Internal Server Error
// Error: Oops!
//     at /app.js:5:15
//     at Layer.handle [as handle_request]
