//     
// EXPOSES:
// - Stack trace (internal paths, code structure)
// - Exact error location
// - Implementation details
```

**✅ AFTER:**
```javascript
app.get('/health', (req, res, next) => {
  try {
    // code
  } catch (error) {
    next(error); // Pass to error handler
  }
});

// Global error handler
app.use((err, req, res, next) => {
  console.error('Error:', err); // Log for debugging

  const statusCode = err.status || 500;
  const response = {
    message: err.message || 'Internal server error'
  };

  // Only show stack in development
  if (process.env.NODE_ENV === 'development') {
    response.stack = err.stack;
  }

  res.status(statusCode).json(response);
});

// Returns:
// { "message": "Internal server error" }
// 
// Hides:
// - Stack traces
// - Implementation details
// - Internal paths
```

---

### Issue #7: No CORS Configuration

**❌ BEFORE:**
```javascript
const app = express();
// No CORS configuration

// What happens?
// Browser blocks cross-origin requests
// OR defaults to open CORS (vulnerable)

// Attacker website can:
// - Make requests from attacker.com to your API
