// Security Testing Examples and Best Practices
// File: security.test.js

const request = require('supertest');
const app = require('./app_secure');

describe('Security Tests', () => {

  // ========================================================================
  // 1. SECURITY HEADERS TESTS
  // ========================================================================

  describe('Security Headers', () => {
    test('should include X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBe('nosniff');
    });

    test('should include X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBeDefined();
    });

    test('should include X-XSS-Protection header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-xss-protection']).toBeDefined();
    });

    test('should include Strict-Transport-Security header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['strict-transport-security']).toBeDefined();
    });

    test('should not expose Express version', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-powered-by']).toBeUndefined();
    });
  });

  // ========================================================================
  // 2. INPUT VALIDATION TESTS
  // ========================================================================

  describe('Input Validation', () => {
    test('should reject invalid limit parameter', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 'invalid' });

      expect(response.status).toBe(400);
      expect(response.body.errors).toBeDefined();
    });

    test('should reject limit > 100', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 101 });

      expect(response.status).toBe(400);
    });

    test('should reject negative offset', async () => {
      const response = await request(app)
        .get('/users')
        .query({ offset: -1 });

      expect(response.status).toBe(400);
    });

    test('should accept valid parameters', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 10, offset: 0 });

      expect(response.status).toBe(200);
      expect(response.body.data).toBeDefined();
    });
  });

  // ========================================================================
  // 3. CORS TESTS
  // ========================================================================

  describe('CORS Configuration', () => {
    test('should handle preflight requests', async () => {
      const response = await request(app)
        .options('/users')
        .set('Origin', 'http://localhost:3000')
        .set('Access-Control-Request-Method', 'GET');

      expect(response.status).toBe(200);
    });

    test('should include CORS headers for allowed origins', async () => {
      const response = await request(app)
        .get('/users')
        .set('Origin', 'http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });
  });

  // ========================================================================
  // 4. RATE LIMITING TESTS
  // ========================================================================

  describe('Rate Limiting', () => {
    test('should include RateLimit headers', async () => {
      const response = await request(app).get('/health');

      expect(response.headers['ratelimit-limit']).toBeDefined();
      expect(response.headers['ratelimit-remaining']).toBeDefined();
      expect(response.headers['ratelimit-reset']).toBeDefined();
    });

    // Note: This test would need a mock of express-rate-limit to fully test
    // In real scenarios, use integration tests with rate limit middleware
  });

  // ========================================================================
  // 5. ERROR HANDLING TESTS
  // ========================================================================

  describe('Error Handling', () => {
    test('should return 404 for unknown routes', async () => {
      const response = await request(app).get('/unknown-route');

      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not found');
    });

    test('should not expose stack traces in production', async () => {
      const originalEnv = process.env.NODE_ENV;
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/unknown-route');

      expect(response.body.stack).toBeUndefined();
      process.env.NODE_ENV = originalEnv;
    });

    test('should return valid JSON on errors', async () => {
      const response = await request(app)
        .get('/users')
        .query({ limit: 'invalid' });

      expect(response.type).toMatch(/json/);
      expect(response.body).toHaveProperty('errors');
    });
  });

  // ========================================================================
  // 6. PAYLOAD SIZE TESTS
  // ========================================================================

  describe('Payload Size Limits', () => {
    test('should reject oversized payloads', async () => {
      const largePayload = 'x'.repeat(11 * 1024); // 11KB (limit is 10KB)

      const response = await request(app)
        .post('/data')
        .send({ data: largePayload });

      // Should either reject or return 413 Payload Too Large
      expect([413, 400]).toContain(response.status);
    });
  });

  // ========================================================================
  // 7. CONTENT TYPE VALIDATION
  // ========================================================================

  describe('Content Type Validation', () => {
    test('should parse JSON content', async () => {
      const response = await request(app)
        .post('/echo')
        .set('Content-Type', 'application/json')
        .send({ message: 'test' });

      expect(response.status).not.toBe(400);
    });

    test('should handle URL-encoded content', async () => {
      const response = await request(app)
        .post('/echo')
        .set('Content-Type', 'application/x-www-form-urlencoded')
        .send('message=test');

      expect(response.status).not.toBe(400);
    });
  });

  // ========================================================================
  // 8. HTTP METHOD VALIDATION
  // ========================================================================

  describe('HTTP Methods', () => {
    test('should reject unsupported methods', async () => {
      const response = await request(app)
        .delete('/health');

      expect(response.status).toBe(404);
    });

    test('should allow GET on /health', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
    });
  });

  // ========================================================================
  // 9. RESPONSE VALIDATION
  // ========================================================================

  describe('Response Validation', () => {
    test('should not expose sensitive information in errors', async () => {
      const response = await request(app).get('/unknown');

      const bodyString = JSON.stringify(response.body);
      expect(bodyString).not.toMatch(/password|secret|key|token/i);
    });

    test('should return valid JSON', async () => {
      const response = await request(app).get('/health');
      expect(response.type).toMatch(/json/);
      expect(() => JSON.parse(response.text)).not.toThrow();
    });

    test('should include proper status codes', async () => {
      const healthResponse = await request(app).get('/health');
      expect(healthResponse.status).toBe(200);

      const notFoundResponse = await request(app).get('/unknown');
      expect(notFoundResponse.status).toBe(404);
    });
  });

});

