// Secure version of the application with security best practices implemented

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');
const winston = require('winston');

const app = express();

// ============ SECURITY MIDDLEWARE ============

// 1. Security Headers
app.use(helmet());

// 2. CORS Configuration
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 3600
}));

// 3. Rate Limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true,
  legacyHeaders: false,
});

const strictLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 5, // limit each IP to 5 requests per hour
});

app.use(limiter);

// ============ LOGGING ============

const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.json(),
  defaultMeta: { service: 'app' },
  transports: [
    new winston.transports.File({ filename: 'error.log', level: 'error' }),
    new winston.transports.File({ filename: 'combined.log' }),
  ],
});

if (process.env.NODE_ENV !== 'production') {
  logger.add(new winston.transports.Console({
    format: winston.format.simple(),
  }));
}

// Request logging middleware
app.use((req, res, next) => {
  logger.info({
    method: req.method,
    path: req.path,
    ip: req.ip,
    userAgent: req.get('user-agent'),
  });
  next();
});

// ============ ROUTES ============

app.get('/health', (req, res) => {
  logger.info('Health check requested');
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Protected endpoint requiring authentication (example)
app.get('/users', strictLimiter, (req, res) => {
  // In a real application, verify authentication token here
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    logger.warn('Unauthorized access attempt to /users endpoint');
    return res.status(401).json({ error: 'Unauthorized' });
  }

  logger.info('Users endpoint accessed by authenticated user');

  // Return limited user information
  // Never expose sensitive data like email without authorization
  res.json([
    { id: 1, name: 'Alice' },
    { id: 2, name: 'Bob' },
  ]);
});

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  logger.warn(`404 Not Found: ${req.method} ${req.path}`);
  res.status(404).json({ error: 'Not Found' });
});

// Global error handler
app.use((err, req, res, next) => {
  logger.error({
    message: err.message,
    stack: err.stack,
    method: req.method,
    path: req.path,
  });

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = process.env.NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(statusCode).json({ error: message });
});

// ============ SERVER STARTUP ============

// Validate environment variables
const requiredEnvVars = ['NODE_ENV'];
const missingEnvVars = requiredEnvVars.filter(envVar => !process.env[envVar]);

if (missingEnvVars.length > 0) {
  logger.error(`Missing required environment variables: ${missingEnvVars.join(', ')}`);
  process.exit(1);
}

const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

const server = app.listen(PORT, () => {
  logger.info(`Server running on port ${PORT} in ${NODE_ENV} mode`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  logger.info('SIGTERM received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

process.on('SIGINT', () => {
  logger.info('SIGINT received, shutting down gracefully');
  server.close(() => {
    logger.info('Server closed');
    process.exit(0);
  });
});

// Handle unhandled promise rejections
process.on('unhandledRejection', (reason, promise) => {
  logger.error({
    message: 'Unhandled Rejection',
    reason: reason,
    promise: promise,
  });
  process.exit(1);
});

module.exports = app;

// Example security tests for the Express application
// Using Jest and Supertest

const request = require('supertest');
const app = require('./app.js.secure');

describe('Security Tests', () => {

  // ========== HEADERS TESTS ==========
  describe('Security Headers', () => {
    test('should include X-Content-Type-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-content-type-options']).toBeDefined();
    });

    test('should include X-Frame-Options header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-frame-options']).toBeDefined();
    });

    test('should include Content-Security-Policy header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['content-security-policy']).toBeDefined();
    });

    test('should not expose X-Powered-By header', async () => {
      const response = await request(app).get('/health');
      expect(response.headers['x-powered-by']).toBeUndefined();
    });
  });

  // ========== RATE LIMITING TESTS ==========
  describe('Rate Limiting', () => {
    test('should allow requests within limit', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
      expect(response.headers['ratelimit-limit']).toBeDefined();
    });

    test('should return 429 when rate limit exceeded', async () => {
      // This is a simplified test - actual implementation would need
      // to simulate multiple rapid requests
      const responses = [];
      for (let i = 0; i < 101; i++) {
        responses.push(request(app).get('/health'));
      }

      const results = await Promise.all(responses);
      const lastResponse = results[results.length - 1];

      // Should eventually hit rate limit (simplified check)
      expect(lastResponse.headers['ratelimit-limit']).toBeDefined();
    });
  });

  // ========== AUTHENTICATION TESTS ==========
  describe('Authentication', () => {
    test('should reject /users endpoint without token', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(401);
      expect(response.body.error).toBe('Unauthorized');
    });

    test('should accept /users endpoint with valid token', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer valid-token-here');

      // Note: This would need actual JWT validation in real app
      expect(response.status).not.toBe(401);
    });
  });

  // ========== CORS TESTS ==========
  describe('CORS', () => {
    test('should include CORS headers', async () => {
      const response = await request(app)
        .get('/health')
        .origin('http://localhost:3000');

      expect(response.headers['access-control-allow-origin']).toBeDefined();
    });

    test('should reject requests from unauthorized origins', async () => {
      const response = await request(app)
        .get('/health')
        .origin('http://malicious.com');

      // Should either not include CORS headers or include appropriate restrictions
      const allowedOrigin = response.headers['access-control-allow-origin'];
      expect(allowedOrigin).not.toBe('http://malicious.com');
    });
  });

  // ========== ERROR HANDLING TESTS ==========
  describe('Error Handling', () => {
    test('should return 404 for non-existent routes', async () => {
      const response = await request(app).get('/non-existent-route');
      expect(response.status).toBe(404);
      expect(response.body.error).toBe('Not Found');
    });

    test('should not expose error stack traces in production', async () => {
      process.env.NODE_ENV = 'production';

      const response = await request(app).get('/trigger-error');

      if (response.status === 500) {
        expect(response.body.error).not.toContain('at');
        expect(response.body.error).not.toContain('stack');
      }

      delete process.env.NODE_ENV;
    });

    test('should return JSON error responses', async () => {
      const response = await request(app).get('/non-existent-route');
      expect(response.type).toMatch(/json/);
    });
  });

  // ========== DATA EXPOSURE TESTS ==========
  describe('Data Exposure', () => {
    test('should not expose email addresses without authentication', async () => {
      const response = await request(app).get('/users');
      expect(response.status).toBe(401);
      // Should not reach here, but if data were exposed:
      if (response.body[0]) {
        expect(response.body[0].email).toBeUndefined();
      }
    });

    test('should return minimal user data', async () => {
      const response = await request(app)
        .get('/users')
        .set('Authorization', 'Bearer valid-token');

      // Only name should be exposed, not email
      if (response.status === 200) {
        expect(response.body[0]).toHaveProperty('name');
        expect(response.body[0]).not.toHaveProperty('email');
      }
    });
  });

  // ========== HTTP METHOD TESTS ==========
  describe('HTTP Methods', () => {
    test('should only allow GET on /health', async () => {
      const healthRoute = request(app).post('/health');
      const response = await healthRoute;

      // Should either return 405 or 404
      expect([404, 405]).toContain(response.status);
    });

    test('should not allow DELETE or PUT on /users', async () => {
      const deleteResponse = await request(app).delete('/users');
      const putResponse = await request(app).put('/users');

      expect([404, 405]).toContain(deleteResponse.status);
      expect([404, 405]).toContain(putResponse.status);
    });
  });

  // ========== INPUT VALIDATION TESTS ==========
  describe('Input Validation', () => {
    test('should validate query parameters', async () => {
      const response = await request(app)
        .get('/health')
        .query({ '<script>alert("xss")</script>': 'test' });

      // Should sanitize or reject malicious input
      expect(response.status).not.toBe(200);
    });

    test('should reject oversized payloads', async () => {
      const largePayload = 'a'.repeat(100000);
      const response = await request(app)
        .post('/users')
        .send({ data: largePayload });

      // Should be rejected (413 Payload Too Large) or return error
      expect([400, 413, 404]).toContain(response.status);
    });
  });

  // ========== HEALTH CHECK TESTS ==========
  describe('Health Check', () => {
    test('should return 200 on /health', async () => {
      const response = await request(app).get('/health');
      expect(response.status).toBe(200);
    });

    test('should return valid JSON', async () => {
      const response = await request(app).get('/health');
      expect(response.type).toMatch(/json/);
      expect(response.body).toHaveProperty('status');
      expect(response.body).toHaveProperty('timestamp');
    });
  });
});

// ========== INTEGRATION TESTS ==========
describe('Integration Tests', () => {
  test('should handle concurrent requests securely', async () => {
    const requests = [];
    for (let i = 0; i < 10; i++) {
      requests.push(request(app).get('/health'));
    }

    const responses = await Promise.all(requests);
    responses.forEach(response => {
      expect(response.status).toBe(200);
      expect(response.headers['x-content-type-options']).toBeDefined();
    });
  });

  test('should maintain security headers on all endpoints', async () => {
    const endpoints = ['/health', '/users'];

    for (const endpoint of endpoints) {
      const response = await request(app).get(endpoint);
      expect(response.headers['x-content-type-options']).toBeDefined();
      expect(response.headers['x-frame-options']).toBeDefined();
