const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const { query, validationResult } = require('express-validator');

const app = express();

// Environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';

// ============ SECURITY MIDDLEWARE ============

// Set security HTTP headers
app.use(helmet());

// Configure CORS properly
app.use(cors({
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  maxAge: 86400 // 24 hours
}));

// Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.'
});

const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // stricter limit for auth endpoints
  skipSuccessfulRequests: true
});

app.use(limiter);

// Parse JSON with size limit
app.use(express.json({ limit: '10kb' }));

// HTTPS redirect in production
if (NODE_ENV === 'production') {
  app.use((req, res, next) => {
    if (req.header('x-forwarded-proto') !== 'https') {
      res.redirect(`https://${req.header('host')}${req.url}`);
    } else {
      next();
    }
  });
}

// Request logging (structured)
app.use((req, res, next) => {
  const start = Date.now();
  res.on('finish', () => {
    const duration = Date.now() - start;
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      duration: `${duration}ms`,
      ip: req.ip,
      userAgent: req.get('user-agent')
    }));
  });
  next();
});

// ============ AUTHENTICATION MIDDLEWARE ============

// Simple token authentication (in production, use JWT with proper validation)
const authenticate = (req, res, next) => {
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ 
      error: 'Unauthorized - missing or invalid token' 
    });
  }

  const token = authHeader.substring(7);

  // TODO: Validate token with your auth service
  // For now, just check it exists
  if (!token || token.length < 10) {
    return res.status(401).json({ 
      error: 'Unauthorized - invalid token format' 
    });
  }

  // Store token in request for logging
  req.token = token.substring(0, 10) + '***';
  next();
};

// ============ ROUTES ============

// Health check (public, no auth required)
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV
  });
});

// Protected users endpoint
app.get('/users',
  authenticate,
  query('limit').optional().isInt({ min: 1, max: 100 }),
  (req, res) => {
    // Validate query parameters
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid parameters',
        details: errors.array() 
      });
    }

    const limit = req.query.limit ? parseInt(req.query.limit, 10) : 2;

    // In production, fetch from database with parameterized queries
    const users = [
      { id: 1, name: 'Alice', email: 'alice@example.com' },
      { id: 2, name: 'Bob', email: 'bob@example.com' },
    ];

    res.json(users.slice(0, limit));
  }
);

// ============ ERROR HANDLING ============

// 404 handler
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// Global error handler (must be last)
app.use((err, req, res, next) => {
  console.error(JSON.stringify({
    timestamp: new Date().toISOString(),
    error: err.message,
    stack: NODE_ENV === 'production' ? undefined : err.stack,
    path: req.path,
    method: req.method
  }));

  // Don't expose stack traces in production
  const message = NODE_ENV === 'production' 
    ? 'Internal Server Error' 
    : err.message;

  res.status(err.status || 500).json({ 
    error: message,
    ...(NODE_ENV !== 'production' && { details: err.stack })
  });
});

// ============ SERVER ============

const server = app.listen(PORT, () => {
  console.log(JSON.stringify({
    timestamp: new Date().toISOString(),
    message: 'Server started',
    port: PORT,
    environment: NODE_ENV,
    nodeVersion: process.version
  }));
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

