app.post('/data', (req, res) => {
  const data = pickle.loads(req.body.data); // DANGEROUS!
});
```

**Secure Implementation:**
```javascript
// Use safe serialization formats
app.post('/data', (req, res) => {
  const data = JSON.parse(req.body.data); // Safer, but still validate
  // Validate data structure
  if (!data.id || typeof data.id !== 'string') {
    return res.status(400).json({ error: 'Invalid input' });
  }
});
```

---

### 9. CWE-400: Uncontrolled Resource Consumption 🟡 MEDIUM

**Vulnerable Code:**
```javascript
app.get('/download', (req, res) => {
  const url = req.query.url;
  https.get(url, (response) => {
    response.pipe(res); // DANGEROUS - no size limit!
  });
});
```

**Secure Implementation:**
```javascript
const https = require('https');

app.get('/download', (req, res) => {
  const url = req.query.url;

  const options = {
    timeout: 5000, // 5 second timeout
  };

  https.get(url, options, (response) => {
    let size = 0;
    const MAX_SIZE = 10 * 1024 * 1024; // 10MB limit

    response.on('data', (chunk) => {
      size += chunk.length;
      if (size > MAX_SIZE) {
        response.destroy();
        return res.status(413).json({ error: 'File too large' });
      }
    });

    response.pipe(res);
  });
});
```

---

### 10. CWE-643: Improper Verification of Data Authenticity 🔴 HIGH

**Vulnerable Code:**
```javascript
app.post('/api/action', (req, res) => {
  const { userId, action } = req.body;
  executeAction(userId, action); // No verification!
});
```

**Secure Implementation:**
```javascript
const jwt = require('jsonwebtoken');

app.post('/api/action', authenticate, (req, res) => {
  // Verify token
  const token = req.headers.authorization?.split(' ')[1];
  const decoded = jwt.verify(token, process.env.JWT_SECRET);

  // Ensure requester is authorized
  if (decoded.userId !== req.body.userId) {
    return res.status(403).json({ error: 'Forbidden' });
  }

  const { userId, action } = req.body;
  executeAction(userId, action);
});
```

---

### 11. CWE-1021: Improper Restriction of Rendered UI Layers or Frames 🟡 MEDIUM

**Vulnerable Code:**
```javascript
// No X-Frame-Options header
app.get('/page', (req, res) => {
  res.send('<html>...</html>'); // Can be framed!
});
```

**Secure Implementation:**
```javascript
const helmet = require('helmet');
app.use(helmet()); // Sets X-Frame-Options: DENY by default

// Or manually
app.use((req, res, next) => {
  res.setHeader('X-Frame-Options', 'DENY');
  next();
});
```

---

### 12. CWE-611: Improper Restriction of XML External Entity Reference 🔴 HIGH

**Vulnerable Code:**
```javascript
const xml2js = require('xml2js');

app.post('/parse-xml', (req, res) => {
  const parser = new xml2js.Parser(); // DANGEROUS - XXE vulnerability!
  parser.parseString(req.body, (err, result) => {
    res.json(result);
  });
});
```

**Secure Implementation:**
```javascript
const xml2js = require('xml2js');

app.post('/parse-xml', (req, res) => {
  const parser = new xml2js.Parser({
    strict: true,
    resolveNamespace: false,
    xmlns: false,
    // Disable external entity processing
    disableNS: true
  });

  parser.parseString(req.body, (err, result) => {
    if (err) return res.status(400).json({ error: 'Invalid XML' });
    res.json(result);
  });
});
```

