## 8. Secure Headers Configuration

### Complete Helmet Configuration
```javascript
const helmet = require('helmet');

app.use(helmet({
  // Content Security Policy
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      scriptSrc: ["'self'", "https://cdn.example.com"],
      styleSrc: ["'self'", "'unsafe-inline'"], // Minimize unsafe-inline
      imgSrc: ["'self'", "data:", "https:"],
      fontSrc: ["'self'", "data:"],
      connectSrc: ["'self'", "https://api.example.com"],
      frameSrc: ["'none'"],
      objectSrc: ["'none'"]
    }
  },

  // Prevent browsers from sniffing MIME types
  noSniff: true,

  // Prevent clickjacking
  frameguard: {
    action: 'deny'
  },

  // XSS protection (legacy)
  xssFilter: true,

  // HSTS
  hsts: {
    maxAge: 31536000, // 1 year
    includeSubDomains: true,
    preload: true
  },

  // Disable referrer
  referrerPolicy: {
    policy: 'strict-origin-when-cross-origin'
  },

  // Permissions policy
  permittedCrossDomainPolicies: false
}));
```

---

## 9. Error Handling - Secure Pattern

```javascript
class ApiError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
  }
}

// Error handler middleware
app.use((err, req, res, next) => {
  console.error('Error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString()
  });

  // Don't expose implementation details
  const isDevelopment = process.env.NODE_ENV === 'development';

  let response = {
    message: 'Internal Server Error',
    code: err.code || 'INTERNAL_ERROR'
  };

  if (isDevelopment) {
    response.stack = err.stack;
  }

  const statusCode = err.statusCode || 500;
  res.status(statusCode).json(response);
});

// Usage
app.get('/risky-operation', async (req, res, next) => {
  try {
    // ... do something
  } catch (err) {
    next(new ApiError('Operation failed', 400));
  }
});
```

---

## 10. Secure Logging Pattern

```javascript
function sanitizeForLogging(data) {
  const sensitive = ['password', 'token', 'secret', 'apiKey', 'accessToken'];
  const copy = JSON.parse(JSON.stringify(data));

  function sanitize(obj) {
    for (const key in obj) {
      if (sensitive.some(s => key.toLowerCase().includes(s))) {
        obj[key] = '***REDACTED***';
      } else if (typeof obj[key] === 'object') {
        sanitize(obj[key]);
      }
    }
  }

  sanitize(copy);
  return copy;
}

app.use((req, res, next) => {
  res.on('finish', () => {
    console.log(JSON.stringify({
      timestamp: new Date().toISOString(),
      method: req.method,
      path: req.path,
      status: res.statusCode,
      user: req.user?.id,
      body: sanitizeForLogging(req.body),
      query: sanitizeForLogging(req.query)
    }));
  });
  next();
});
```

