## 11. Rate Limiting Advanced

### Multiple Rate Limiters
```javascript
const rateLimit = require('express-rate-limit');

// General API limiter
const apiLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 100,
  keyGenerator: (req, res) => req.user?.id || req.ip,
  skip: (req, res) => req.user?.role === 'admin'
});

// Strict login limiter
const loginLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5,
  skipSuccessfulRequests: true,
  message: 'Too many login attempts'
});

// Very strict password reset limiter
const passwordResetLimiter = rateLimit({
  windowMs: 60 * 60 * 1000, // 1 hour
  max: 3
});

app.use('/api/', apiLimiter);
app.post('/login', loginLimiter, async (req, res) => {
  // ...
});
app.post('/forgot-password', passwordResetLimiter, async (req, res) => {
  // ...
});
```

---

## 12. Environment Validation

```javascript
function validateEnvironment() {
  const required = {
    NODE_ENV: ['development', 'production', 'test'],
    JWT_SECRET: null, // Just needs to exist
    PORT: /^\d+$/,
    DATABASE_URL: /^postgres:\/\//
  };

  const errors = [];

  for (const [key, validation] of Object.entries(required)) {
    const value = process.env[key];

    if (!value) {
      errors.push(`Missing required variable: ${key}`);
      continue;
    }

    if (Array.isArray(validation) && !validation.includes(value)) {
      errors.push(`${key} must be one of: ${validation.join(', ')}`);
    } else if (validation instanceof RegExp && !validation.test(value)) {
      errors.push(`${key} has invalid format`);
    }
  }

  if (errors.length > 0) {
    console.error('Environment validation errors:');
    errors.forEach(err => console.error(`  - ${err}`));
    process.exit(1);
  }

  console.log('✓ Environment validated');
}

validateEnvironment();
```

