// Secured version of the application with security best practices

const express = require('express');
const helmet = require('helmet');
const cors = require('cors');
const rateLimit = require('express-rate-limit');
const morgan = require('morgan');
const { query, validationResult } = require('express-validator');

const app = express();

// ============================================
// Security Middleware
// ============================================

// 1. Add security headers
app.use(helmet());

// 2. Configure CORS - restrict to specific origins
app.use(cors({
  origin: process.env.CORS_ORIGIN || 'http://localhost:3000',
  credentials: true,
  methods: ['GET', 'POST'],
  optionsSuccessStatus: 200,
  maxAge: 600
}));

// 3. Rate limiting
const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // limit each IP to 100 requests per windowMs
  message: 'Too many requests from this IP, please try again later.',
  standardHeaders: true, // Return rate limit info in `RateLimit-*` headers
  legacyHeaders: false, // Disable `X-RateLimit-*` headers
});

app.use(limiter);

// 4. Request logging
app.use(morgan('combined')); // Use morgan for request logging

// 5. Middleware to parse JSON bodies safely
app.use(express.json({ limit: '10mb' })); // Limit request body size

// ============================================
// Routes
// ============================================

app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    version: process.env.APP_VERSION || '1.0.0'
  });
});

// Health check with authentication example
app.get('/users', 
  // Input validation
  query('limit')
    .optional()
    .isInt({ min: 1, max: 100 })
    .toInt(),
  (req, res) => {
    // Check for validation errors
    const errors = validationResult(req);
    if (!errors.isEmpty()) {
      return res.status(400).json({ 
        error: 'Invalid input',
        details: errors.array() 
      });
    }

    const limit = req.query.limit || 10;

    // TODO: Add authentication check here
    // if (!req.user) return res.status(401).json({ error: 'Unauthorized' });

    try {
      const users = [
        { id: 1, name: 'Alice', email: 'alice@example.com' },
        { id: 2, name: 'Bob', email: 'bob@example.com' },
      ].slice(0, limit);

      res.json(users);
    } catch (error) {
      // Log error internally but don't expose details
      console.error('Error fetching users:', error);
      res.status(500).json({ 
        error: 'Internal Server Error',
        // Only expose details in development
        ...(process.env.NODE_ENV !== 'production' && { message: error.message })
      });
    }
  }
);

// ============================================
// Global Error Handler
// ============================================

app.use((err, req, res, next) => {
  console.error('Unhandled error:', {
    message: err.message,
    stack: err.stack,
    path: req.path,
    method: req.method,
    ip: req.ip
  });

  res.status(err.status || 500).json({
    error: 'Internal Server Error',
    // Only expose error details in development
    ...(process.env.NODE_ENV !== 'production' && { 
      message: err.message,
      details: err.details 
    })
  });
});

// Handle 404 errors
app.use((req, res) => {
  res.status(404).json({ 
    error: 'Not Found',
    path: req.path 
  });
});

// ============================================
// Server Startup
// ============================================

const PORT = process.env.PORT || 3000;
const HOST = process.env.HOST || 'localhost';

const server = app.listen(PORT, HOST, () => {
  console.log(`✓ Server running on ${HOST}:${PORT}`);
  console.log(`✓ Environment: ${process.env.NODE_ENV || 'development'}`);
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM received, shutting down gracefully...');
  server.close(() => {
    console.log('Server closed');
    process.exit(0);
  });
});

module.exports = app;
